head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/STACKTOTAL/data/STACKTOTAL.json";   // 순수 데이터(columns)
scwin.CHART_CONFIG = {
    dataOpts: { labels: true },                                 // 개별 막대 값 라벨
    extend: {
        stackbar: {
            aggregate: {                                        // ★ 누적 합계 표시
                show: true,
                labelFormat: function (value) { return value + "(원)"; },
                labelColor: "red",
                labelFontSize: 12,
                labelFontWeight: "bold"
            }
        }
    }
};

scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData("stackbar", data, chartWrap, scwin.CHART_CONFIG);
};
